<template><section class="finance-panel"><header><div><h2>Bank connections &amp; reconciliation</h2><p>Link {{ agencyName }}’s bank accounts, review activity, and match recorded expenses.</p></div><button :disabled="busy" @click="load()">Refresh</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="data"><p v-if="isDemo" class="finance-callout">Simulated bank activity. This demo cannot connect a real bank or send payments.</p><p v-else-if="!data.enabled" class="finance-callout">Bank access needs organization consent in Settings and Stripe deployment activation.</p><form v-if="!isDemo" @submit.prevent="connect"><label class="check"><input v-model="consent" type="checkbox" required :disabled="busy||!data.enabled" /> I am authorized to share this organization’s full transaction activity for financial operations.</label><button class="primary" :disabled="busy||!data.enabled||!consent">Connect bank through Stripe</button></form><div v-for="a in data.accounts" :key="a.id" class="bank-account"><strong>{{ a.institution }} · {{ a.name }} · •••• {{ a.last4 }}</strong><span>{{ label(a.status) }}</span><p v-if="a.lastError">{{ a.lastError }}</p><div v-if="!isDemo" class="finance-actions"><button :disabled="busy||!data.enabled||!a.syncEnabled" @click="action(a.id,'sync')">Import available updates</button><button :disabled="busy" @click="disconnectId=a.id">Disconnect</button><template v-if="disconnectId===a.id"><span>Revoke this bank connection?</span><button @click="action(a.id,'disconnect')">Confirm disconnect</button><button @click="disconnectId=null">Cancel</button></template></div></div><p>Imported activity is evidence for reconciliation. It does not create expenses, count spending twice, or initiate transfers.</p><div class="finance-table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Status</th><th>Expense match</th></tr></thead><tbody><tr v-for="row in data.entries" :key="row.id"><td>{{ new Date(row.transactedAt*1000).toLocaleDateString() }}</td><td>{{ row.description }}</td><td>{{ new Intl.NumberFormat('en-US',{style:'currency',currency:row.currency}).format(row.amountCents/100) }}</td><td><span class="finance-badge">{{ label(row.status) }} · {{ label(row.reviewStatus) }}</span></td><td><template v-if="row.expenseId">Expense #{{ row.expenseId }}<button v-if="row.reviewStatus==='needs_review'" :disabled="busy" @click="match(row,row.expenseId)">Reconfirm evidence</button></template><template v-else><select v-model="matches[row.id]" aria-label="Match paid expense"><option value="">Select paid expense</option><option v-for="e in paidMatches(row)" :key="e.id" :value="e.id">#{{ e.id }} {{ e.title }}</option></select><button :disabled="busy||!matches[row.id]" @click="confirmId=row.id">Match</button><div v-if="confirmId===row.id"><p>Confirm the payee, reference, and amount match the recorded payment.</p><button @click="match(row,matches[row.id])">Confirm match</button><button @click="confirmId=null">Cancel</button></div></template></td></tr></tbody></table></div><p v-if="!data.entries.length" class="finance-empty">No imported bank activity yet.</p><div class="finance-actions"><button v-if="after" @click="load(0)">First page</button><button v-if="data.nextAfter" @click="load(data.nextAfter)">Next page</button></div></template></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {loadStripe} from '@stripe/stripe-js';import api from '../../services/api';import {money,label} from './financeForms';
const props=defineProps({agencyId:Number,agencyName:String,isDemo:Boolean,expenses:Array});const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),consent=ref(false),matches=ref({}),confirmId=ref(null),disconnectId=ref(null),after=ref(0);let version=0;
const paidMatches=row=>(props.expenses||[]).filter(e=>e.status==='paid'&&Number(e.amount_cents)===-row.amountCents&&row.status==='posted'&&row.currency==='usd');
async function load(cursor=0){const v=++version;busy.value=true;error.value='';data.value=null;try{const r=await api.get(`/finance-operations/${props.agencyId}/bank`,{params:cursor?{after:cursor}:{}});if(v===version){data.value=r.data;after.value=cursor;}}catch(e){if(v===version)error.value=e.response?.data?.error?.message||'Bank data is unavailable';}finally{if(v===version)busy.value=false;}}
async function connect(){const v=version,agencyId=props.agencyId;busy.value=true;error.value='';try{const {data:s}=await api.post(`/finance-operations/${agencyId}/bank/session`,{ownerAuthorized:consent.value,requestKey:crypto.randomUUID()});if(v!==version)return;const stripe=await loadStripe(s.publishableKey);if(v!==version)return;if(!stripe)throw Error();const r=await stripe.collectFinancialConnectionsAccounts({clientSecret:s.clientSecret});if(v!==version)return;if(r.error)throw Error();if(!r.financialConnectionsSession?.accounts?.length){notice.value='No accounts connected';return;}await api.post(`/finance-operations/${agencyId}/bank/complete`,{sessionKey:s.sessionKey});if(v===version){consent.value=false;await load();}}catch(e){if(v===version)error.value=e.response?.data?.error?.message||'Connection did not complete. Refresh before reconnecting.';}finally{if(v===version)busy.value=false;}}
async function action(accountId,type){const v=version;busy.value=true;error.value='';try{await api.post(`/finance-operations/${props.agencyId}/bank/${accountId}/${type}`,{});if(v===version){disconnectId.value=null;notice.value=type==='disconnect'?'Bank connection disconnected.':'Available updates checked. New bank refreshes arrive on Stripe’s schedule.';await load(after.value);}}catch(e){if(v===version)error.value=e.response?.data?.error?.message||'Bank action could not complete';}finally{if(v===version)busy.value=false;}}
async function match(row,expenseId){const v=version;busy.value=true;error.value='';try{await api.post(`/finance-operations/${props.agencyId}/bank/entries/${row.id}/match`,{expenseId:Number(expenseId),confirmed:true});if(v===version){confirmId.value=null;await load(after.value);}}catch(e){if(v===version)error.value=e.response?.data?.error?.message||'Match needs review';}finally{if(v===version)busy.value=false;}}
watch(()=>props.agencyId,()=>{data.value=null;consent.value=false;matches.value={};confirmId.value=null;disconnectId.value=null;load();},{immediate:true});onBeforeUnmount(()=>{version++;});
</script>
